+export function nextAction(state: Session, config: Config): Action {
+  if (config.cadence === 'off') return 'none';
+  if (isIdleWithWork(state, config)) return 'nudge';
+  if (state.pending >= config.batchSize) return 'checkpoint';
+  return 'none';
+}
+
+function isIdleWithWork(state: Session, config: Config): boolean {
+  return Date.now() - state.lastPromptAt > config.idleMs && state.pending > 0;
+}
